<?php
declare(strict_types=1);
function integerValue(array $b,string $key,int $min,int $max,?int $default=null): int {$v=$b[$key]??$default;if(!is_int($v)||$v<$min||$v>$max)fail(400,'Invalid '.$key);return $v;}
function stringList($v,int $max=50,int $length=200): array {if(!is_array($v)||!array_is_list($v)||count($v)>$max)fail(400,'Invalid list.');foreach($v as$x)if(!is_string($x)||mb_strlen($x)>$length)fail(400,'Invalid list item.');return $v;}
function messagePost(array $message): ?array {
 if(!$message['channelId'])return null;$root=$message;$seen=[];for($i=0;$i<100&&$root['replyToId'];$i++){if(isset($seen[$root['id']]))fail(400,'Reply cycle.');$seen[$root['id']]=true;$parent=entity($root['replyToId'],'message');if(!$parent)break;$root=$parent;}
 foreach(listEntities('post',$message['channelId'])as$p)if($p['rootMessageId']===$root['id'])return $p;return null;
}
function messageAccessible(array $msg,?string $uid=null): bool {
 $uid??=user()['id'];try{canTarget($msg['channelId']?'channels':'conversations',$msg['channelId']??$msg['conversationId'],$uid);}catch(HttpError){return false;}
 $p=messagePost($msg);if(!$p||!$p['private'])return true;return $p['authorId']===$uid||member($p['id'],$uid)!==null||groupCan(mustEntity($p['channelId'],'channel')['groupId'],'manageThreads',$uid);
}
function requireMessageAccess(array $msg,bool $write=false): void {if(!messageAccessible($msg))fail(404,'Message not found.');$p=messagePost($msg);if($write&&$p&&($p['locked']||$p['archived'])&&!groupCan(mustEntity($p['channelId'],'channel')['groupId'],'manageThreads'))fail(403,'Thread is locked or archived.');if($write&&$msg['channelId'])cp(mustEntity($msg['channelId'],'channel'),'sendMessagesInThreads');}
function messageAudience(array $msg,string $type,string $id): array {return array_values(array_filter(audience($type,$id),fn($uid)=>messageAccessible($msg,$uid)));}
function inspectMessagePolicies(array $channel,string $uid,string $text,int $attachmentCount=0): void {
 $settings=settings();if(!groupCan($channel['groupId'],'deleteAnyMessage',$uid)){
  foreach(preg_split('/[\r\n,]+/',$settings['blocked_terms'])as$term)if(trim($term)!==''&&mb_stripos($text,trim($term))!==false)fail(400,'Message contains a blocked term.');
  foreach(listEntities('automod',$channel['groupId'])as$rule){if(!$rule['enabled'])continue;$matched=false;$value='';$config=$rule['config']??[];
   if($rule['triggerType']==='keyword')foreach($config['keywords']??[]as$term)if($term!==''&&mb_stripos($text,$term)!==false){$matched=true;$value=$term;break;}
   if($rule['triggerType']==='mention_spam'){preg_match_all('/<@[^>]+>/', $text,$matches);$matched=count($matches[0])>($config['mentionLimit']??5);}
   if($rule['triggerType']==='spam'){try{throttle('automod:'.$rule['id'].':'.$uid,$config['messageLimit']??5,$config['windowSeconds']??10);}catch(HttpError $e){if($e->status===429)$matched=true;else throw $e;}}
   if(!$matched)continue;putEntity('automod_action',['userId'=>$uid,'groupId'=>$channel['groupId'],'ruleName'=>$rule['name'],'ruleId'=>$rule['id'],'action'=>$rule['action'],'matchedValue'=>$value],$channel['groupId'],$uid);
   if($rule['action']==='timeout'){$seat=member($channel['groupId'],$uid);$seat['timeoutUntil']=now()+min(2419200,(int)($config['timeoutSeconds']??60))*1000;addMember($channel['groupId'],$uid,$seat);}
   if($rule['action']==='alert')notify(mustEntity($channel['groupId'],'group')['ownerId'],'moderation','AutoMod matched',$rule['name'],['userId'=>$uid,'channelId'=>$channel['id']]);else fail(403,'AutoMod blocked this message.');
  }
 }
 if(function_exists('inspectBuiltinMessage'))inspectBuiltinMessage($channel,$uid,$text,$attachmentCount);
}
function forumAdvancedRoutes(string $m,string $path,array $b): ?array {
 if(!preg_match('#^/api/forums/([^/]+)/posts(?:/([^/]+))?(?:/(root|members)(?:/([^/]+))?)?$#',$path,$a))return null;$cid=$a[1];$c=canTarget('channels',$cid);if($c['type']!=='forum')fail(400,'Not a forum.');$id=user()['id'];$pid=$a[2]??null;$manage=groupCan($c['groupId'],'manageThreads');
 if(!$pid){if($m==='GET')return ['posts'=>array_values(array_map(function($p)use($id,$manage){$p['canManageMembers']=$manage||$p['authorId']===$id;$p['memberCount']=count(memberIds($p['id']));$p['replyCount']=count(array_filter(listEntities('message',$p['channelId']),fn($x)=>$x['replyToId']===$p['rootMessageId']&&!$x['deleted']));return $p;},array_filter(listEntities('post',$cid),fn($p)=>!$p['private']||$manage||$p['authorId']===$id||member($p['id'],$id))))];
  if($m==='POST'){$private=$b['private']??false;if(!is_bool($private))fail(400,'Invalid thread privacy.');cp($c,$private?'createPrivateThreads':'createPublicThreads');$title=required($b,'title',200);$content=required($b,'content',10000);return transaction(function()use($b,$cid,$id,$private,$title,$content){$pid=uid();$client='forum-'.$pid;$root='msg-'.substr(hash('sha256',$id.':'.$client),0,48);$p=putEntity('post',['id'=>$pid,'channelId'=>$cid,'rootMessageId'=>$root,'authorId'=>$id,'title'=>$title,'tags'=>stringList($b['tags']??[],10,48),'locked'=>false,'archived'=>false,'private'=>$private,'memberCount'=>1,'canManageMembers'=>true,'replyCount'=>0,'author'=>publicUser(user())],$cid,$id);addMember($pid,$id);$msg=sendMessage('channels',$cid,['content'=>$content,'clientId'=>$client]);emitUsers(messageAudience(mustEntity($root,'message'),'channels',$cid),'forum:post-created',['channelId'=>$cid,'postId'=>$pid]);http_response_code(201);return ['post'=>$p,'message'=>$msg];});}
 }
 $p=mustEntity($pid,'post');if($p['channelId']!==$cid||($p['private']&&!$manage&&$p['authorId']!==$id&&!member($pid,$id)))fail(404,'Post not found.');$sub=$a[3]??'';
 if($sub==='root'&&$m==='GET')return ['message'=>visibleMessage(mustEntity($p['rootMessageId'],'message'))];
 if($sub==='members'){if(!$manage&&$p['authorId']!==$id)fail(403,'Manage Threads or thread ownership required.');$uid=$a[4]??$b['userId']??'';if($m==='GET')return ['members'=>members($pid)];if($m==='POST'){if(!member($c['groupId'],$uid))fail(400,'User is not a group member.');addMember($pid,$uid);}elseif($m==='DELETE'){if($uid===$p['authorId'])fail(400,'Cannot remove thread owner.');sql('DELETE FROM memberships WHERE scope_id=? AND user_id=?',[$pid,$uid]);}else return null;$p['memberCount']=count(memberIds($pid));putEntity('post',$p,$cid,$p['authorId']);return ['ok'=>true];}
 if($m==='PATCH'){if(!$manage&&$p['authorId']!==$id)fail(403,'Cannot edit this post.');foreach(['locked','archived']as$key)if(array_key_exists($key,$b)){if(!is_bool($b[$key]))fail(400,'Invalid thread flag.');$p[$key]=$b[$key];}if(isset($b['title']))$p['title']=required($b,'title',200);if(isset($b['tags']))$p['tags']=stringList($b['tags'],10,48);return ['post'=>putEntity('post',$p,$cid,$p['authorId'])];}return null;
}
function pollAnalytics(array $msg): array {
 if($msg['authorId']!==user()['id'])fail(404,'Analytics are available only to the poll creator.');$p=$msg['poll']??fail(404,'Poll not found.');$voters=[];$options=[];$total=0;$correct=0;$activity=[];
 foreach($p['options']as$o){$total+=count($o['userIds']);$users=[];foreach($o['userIds']as$id){$voters[$id]=true;$u=account($id);$at=$p['voteTimes'][$id]??$msg['createdAt'];if(!$p['anonymous'])$users[]=['id'=>$id,'username'=>$u['username'],'displayName'=>$u['displayName'],'avatarUrl'=>$u['avatarUrl'],'votedAt'=>$at];if(in_array($o['id'],$p['correctOptionIds'],true))$correct++;}$options[]=['id'=>$o['id'],'label'=>$o['label'],'votes'=>count($o['userIds']),'correct'=>in_array($o['id'],$p['correctOptionIds'],true),'voters'=>$users];}
 foreach($options as&$o)$o['percentage']=$total?round($o['votes']/$total*100,1):0;unset($o);for($i=11;$i>=0;$i--){$start=now()-$i*3600000;$activity[]=['at'=>$start,'votes'=>count(array_filter($p['voteTimes']??[],fn($at)=>$at>=$start&&$at<$start+3600000))];}$eligible=count(audience($msg['channelId']?'channels':'conversations',$msg['channelId']??$msg['conversationId']));$highest=max([0,...array_column($options,'votes')]);
 return ['messageId'=>$msg['id'],'question'=>$p['question'],'anonymous'=>$p['anonymous'],'multiple'=>$p['multiple'],'examMode'=>$p['examMode'],'createdAt'=>$msg['createdAt'],'closesAt'=>$p['closesAt'],'closed'=>$p['closed']||($p['closesAt']&&$p['closesAt']<=now()),'totalSelections'=>$total,'uniqueVoters'=>count($voters),'eligibleVoters'=>$eligible,'participationRate'=>$eligible?round(count($voters)/$eligible*100,1):0,'correctAnswers'=>$correct,'accuracyRate'=>count($voters)?round($correct/count($voters)*100,1):0,'leadingOptionIds'=>array_column(array_filter($options,fn($o)=>$o['votes']===$highest),'id'),'options'=>$options,'activity'=>$activity];
}
function advancedChatRoutes(string $m,string $path,array $b): ?array {
 if($path==='/api/mentions'&&$m==='GET'){$uid=user()['id'];return ['messages'=>array_map('visibleMessage',array_slice(array_values(array_filter(array_reverse(listEntities('message')),fn($msg)=>!$msg['deleted']&&in_array($uid,$msg['mentionedUserIds']??[],true)&&messageAccessible($msg))),0,limit()))];}
 if(!preg_match('#^/api/(channels|conversations)/([^/]+)/messages/([^/]+)/(poll/analytics|poll|poll-vote|publish)$#',$path,$a))return null;$type=$a[1];$id=$a[2];$t=canTarget($type,$id);$msg=mustEntity($a[3],'message');if(($msg['channelId']??$msg['conversationId'])!==$id||$msg['deleted'])fail(404,'Message not found.');requireMessageAccess($msg,$m!=='GET');$action=$a[4];
