  if($msg['authorId']!==user()['id'])fail(403,'Only creator can edit polls.');if($msg['poll']['closed']||($msg['poll']['closesAt']&&$msg['poll']['closesAt']<now()))fail(400,'Poll is closed.');$p=newPoll($b);foreach($p['options']as$i=>&$o)if(isset($msg['poll']['options'][$i])){$old=$msg['poll']['options'][$i];$o['id']=$old['id'];$o['userIds']=$old['userIds'];$o['votes']=count($old['userIds']);}unset($o);$correct=$b['correctOptionIndexes']??(isset($b['correctOptionIndex'])?[$b['correctOptionIndex']]:[]);$p['correctOptionIds']=array_map(fn($i)=>$p['options'][$i]['id'],$correct);$p['voteTimes']=$msg['poll']['voteTimes']??[];$msg['poll']=$p;$msg['content']=$p['question'];$msg['editedAt']=now();putEntity('message',$msg,$id,$msg['authorId']);emitMessage($type,$id,'message:poll',$msg);return ['message'=>visibleMessage($msg)];
 }
 if($action==='poll-vote'&&$m==='PUT'){
  if($type==='channels')cp($t,$t['type']==='forum'?'sendMessagesInThreads':'sendMessages');return transaction(function()use($msg,$id,$type,$b){$msg=entity($msg['id'],'message',true);$p=$msg['poll']??fail(404,'Poll not found.');$uid=user()['id'];if($p['closed']||($p['closesAt']&&$p['closesAt']<=now()))fail(400,'Poll closed.');$ids=stringList($b['optionIds']??[],10,64);if(!$p['multiple']&&count($ids)>1)fail(400,'Only one answer allowed.');if($p['examMode']&&(count($ids)!==1||isset($p['voteTimes'][$uid])))fail(400,'Exam answers may only be submitted once.');foreach($ids as$oid)if(!in_array($oid,array_column($p['options'],'id'),true))fail(400,'Invalid poll option.');foreach($p['options']as&$o){$o['userIds']=array_values(array_diff($o['userIds'],[$uid]));if(in_array($o['id'],$ids,true))$o['userIds'][]=$uid;$o['votes']=count($o['userIds']);}unset($o);$p['voteTimes'][$uid]=now();$msg['poll']=$p;putEntity('message',$msg,$id,$msg['authorId']);emitMessage($type,$id,'message:poll',$msg);return ['message'=>visibleMessage($msg)];});
 }
 if($action==='publish'&&$m==='POST'){
  if($type!=='channels'||$t['type']!=='announcement')fail(400,'Only announcement-channel messages can be published.');cp($t,'sendMessages');if(!groupCan($t['groupId'],'manageChannels')&&$msg['authorId']!==user()['id'])fail(403,'Cannot publish this message.');$published=[];foreach(listEntities('follow')as$f)if($f['sourceChannelId']===$id){$target=entity($f['targetChannelId'],'channel');if(!$target)continue;$copy=$msg;$copy['id']='publication-'.substr(hash('sha256',$msg['id'].':'.$target['id']),0,48);$copy['channelId']=$target['id'];$copy['type']='imported';$copy['sourceMessageId']=$msg['id'];$copy['sourceChannelId']=$id;$copy['replyToId']=null;$copy['reactions']=[];if(!entity($copy['id'])){putEntity('message',$copy,$target['id'],$msg['authorId']);emitMessage('channels',$target['id'],'message:created',$copy);}$published[]=$copy['id'];}return ['published'=>count($published),'messageIds'=>$published];
 }
